-- 3.4. Hồ sơ mẫu: Đã xóa để hệ thống bắt đầu với CSDL sạch

CREATE TABLE IF NOT EXISTS `schema_migrations` (
  `version` VARCHAR(80) NOT NULL,
  `applied_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`version`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `auth_credentials` (
  `user_id` VARCHAR(50) NOT NULL,
  `password_hash` VARCHAR(255) NULL,
  `token_version` INT NOT NULL DEFAULT 0,
  `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`user_id`),
  CONSTRAINT `fk_credential_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `dossier_sequences` (
  `year` INT NOT NULL,
  `last_number` INT NOT NULL,
  PRIMARY KEY (`year`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Chỉ đánh dấu sẵn sàng khi toàn bộ cột runtime đã tồn tại.
INSERT IGNORE INTO `schema_migrations` (`version`)
SELECT '20261116_production_storage' WHERE (
  SELECT COUNT(*) FROM information_schema.COLUMNS
  WHERE TABLE_SCHEMA=DATABASE() AND (
    (TABLE_NAME='departments' AND COLUMN_NAME IN ('id','code','name','short_name','dean_name','email','phone','is_active','created_at')) OR
    (TABLE_NAME='users' AND COLUMN_NAME IN ('id','email','name','role','title','department_id','department','phone','avatar','is_active','created_at','updated_at')) OR
    (TABLE_NAME='document_templates' AND COLUMN_NAME IN ('id','code','title','category','description','version','file_name','fields_config','is_active','created_at','updated_at')) OR
    (TABLE_NAME='dossiers' AND COLUMN_NAME IN ('id','code','title','user_id','template_id','department_id','department_name','status','current_version','applicant_email','form_data','has_workshop','has_financial_implication','ten_de_tai','truong_don_vi','status_1a','status_2a','rejected_target','rejection_reason_1a','rejection_reason_2a','form_data_1a','form_data_2a','signature_config','generated_docx_path','generated_pdf_path','docx_file_url','to_trinh_docx_url','ke_hoach_docx_url','approved_pdf_path','precheck_pdf_url','department_signed_files','resubmitted_signed_files','faculty_signed_pdf_url','evidence_files','final_signed_pdf_path','final_pdf_url','revision_note','review_notes','timeline_logs','decision_number','decision_date','khcn_signed','khcn_signed_at','khtc_signed','khtc_signed_at','bgh_signed','bgh_signed_at','drive_folder_url','submitted_at','reviewed_at','faculty_signed_at','completed_at','created_at','updated_at')) OR
    (TABLE_NAME='dossier_versions' AND COLUMN_NAME IN ('id','dossier_id','version_number','form_data','generated_docx_path','generated_pdf_path','edited_by_id','edited_by_name','change_summary','snapshot','created_at')) OR
    (TABLE_NAME='attachments' AND COLUMN_NAME IN ('id','dossier_id','file_name','file_path','file_url','file_type','file_size','uploaded_by','created_at')) OR
    (TABLE_NAME='audit_logs' AND COLUMN_NAME IN ('id','dossier_id','actor_id','actor_name','actor_role','action','from_status','to_status','notes','metadata','created_at')) OR
    (TABLE_NAME='email_notifications' AND COLUMN_NAME IN ('id','dossier_id','recipient_email','recipient_name','subject','content','step_name','attachments','attempts','last_error','next_attempt_at','status','sent_at')) OR
    (TABLE_NAME='schema_migrations' AND COLUMN_NAME IN ('version','applied_at')) OR
    (TABLE_NAME='auth_credentials' AND COLUMN_NAME IN ('user_id','password_hash','token_version','updated_at')) OR
    (TABLE_NAME='dossier_sequences' AND COLUMN_NAME IN ('year','last_number'))
  )
) = 138;

SELECT DATABASE() AS database_name, IF(EXISTS(SELECT 1 FROM schema_migrations WHERE version='20261116_production_storage'), 'READY', 'SCHEMA_INCOMPATIBLE: run npm run db:migrate') AS initialization_status;
